function keyLogic(h) {
  const { T, V, set, canWrite, owner } = h; const ok = canWrite && owner;
  const k1 = !!(V._k1 ?? 1), pick = V._k2 ?? 1, dial = V._k3 ?? 4, k4 = !!V._k4;
  const k2 = pick === 1, k3 = dial === 7, three = k1 && k2 && k3, all = three && k4;
  const on = [k1, k2, k3, all]; const next = on.indexOf(false); const count = on.filter(Boolean).length;
  const card = (i) => 'keyc' + (on[i] ? ' on' : '') + (i === next ? ' next' : '');
  const stt = (i) => on[i] ? T('Turned', '扭咗') : i === next ? T('Your move', '到你') : T('Locked', '鎖住');
  const names = ['RT-AX88U · Garage-Lab', 'RT-AX86U · Maple-Home', 'GT-AX6000 · Office'];
  return { c0: card(0), c1: card(1), c2: card(2), c3: card(3), s0: stt(0), s1: stt(1), s2: stt(2), s3: stt(3),
    k1Cls: 'sw w' + (k1 ? ' on' : ''), k1Aria: k1 ? 'true' : 'false', flip1: () => { if (ok) set({ _k1: k1 ? 0 : 1, _k4: 0 }); },
    routers: names.map((n, i) => ({ label: n, pressed: pick === i ? 'true' : 'false', pick: () => { if (ok) set({ _k2: i, _k4: 0 }); } })), wrong: pick >= 0 && !k2,
    dial, dialUp: () => { if (ok) set({ _k3: Math.min(9, dial + 1), _k4: 0 }); }, dialDn: () => { if (ok) set({ _k3: Math.max(0, dial - 1), _k4: 0 }); }, dialOff: !k3,
    turn: () => { if (ok && three) set({ _k4: 1 }); }, canTurn: three && !k4, cantTurn: !three, turned: k4,
    armed: all, notArmed: !all, count, pct: (count * 25) + '%', reset: () => set({ _k1: 0, _k2: -1, _k3: 4, _k4: 0 }), locked: !owner,
    countTxt: count + ' / 4 ' + T('keys turned', '條鎖匙扭咗'), armTxt: all ? T('Armed. The launch pad is open.', '已經上膛。發射台開咗。') : T('Not armed. Nothing can be sent yet.', '未上膛。暫時乜都送唔出。') };
}

