function useLogic(h) {
  const { T, V, set, canWrite, D } = h; const sp = (s) => { const q = String(s).split('|'); return T(q[0], q[1] === undefined ? q[0] : q[1]); };
  const tab = V._tab ?? 0, per = V._per ?? 1, dir = V._dir ?? 0; const lim = V.lim || '0000000';
  const U = per === 0 ? 'Mbps' : 'GB'; const fmt = (v) => (v >= 100 ? String(Math.round(v)) : v.toFixed(1)) + ' ' + U;
  const rows = D.x.map((d, i) => ({ i, name: d[0], who: sp(d[1]), d: d[2], dn: d[3][per], up: d[4][per] }));
  const mk = (key, cls) => { const list = rows.slice().sort((a, b) => key(b) - key(a)); const top = key(list[0]) || 1; return list.map((r, j) => { const li = lim[r.i] === '1'; return { rk: j + 1, name: r.name, who: r.who, d: r.d, amt: fmt(key(r)), num: key(r), split: '↓ ' + fmt(r.dn) + ' · ↑ ' + fmt(r.up), style: '--j:' + j + ';--b:' + Math.max(5, key(r) / top * 100).toFixed(0) + '%', cls: 'lbr' + cls, limited: li, free: !li, limLabel: li ? T('Limit queued', '限速已排隊') : T('Slow down', '限速'), limit: () => { if (canWrite) set({ lim: lim.slice(0, r.i) + (li ? '0' : '1') + lim.slice(r.i + 1) }); } }; }); };
  const total = mk(r => r.dn + r.up, ''), downs = mk(r => r.dn, ''), ups = mk(r => r.up, ' up');
  const lead = tab === 0 ? total : dir === 0 ? downs : ups;
  const pod = [1, 0, 2].map((ix, k) => ({ rk: ix + 1, name: lead[ix].name, who: lead[ix].who, d: lead[ix].d, amt: lead[ix].amt, cls: 'pod' + (ix === 0 ? ' p1' : ''), style: '--h:' + [250, 320, 205][k] + 'px;--k:' + [1, 0, 2][k], first: ix === 0 }));
  const ones = lim.split('').filter(c => c === '1').length; h.extraPend = ones - (V.lim ? 1 : 0);
  const PER = [T('Right now', '而家'), T('Today', '今日'), T('7 days', '7 日'), T('30 days', '30 日')];
  const verb = tab === 0 ? T('is using the most', '用得最多') : dir === 0 ? T('is downloading the most', '下載得最多') : T('is uploading the most', '上載得最多');
  const sum = lead.reduce((a, r) => a + r.num, 0);
  return { total: total.slice(0, 6), downs: downs.slice(0, 5), ups: ups.slice(0, 5), pod, tab0: tab === 0, tab1: tab === 1, tabIdx: tab,
    tabs: [T('Who\'s using the most', '邊個用得最多'), T('Who\'s uploading or downloading the most', '邊個上載或者下載得最多')].map((label, i) => ({ label, sel: tab === i ? 'true' : 'false', pick: () => set({ _tab: i }) })),
    title: lead[0].name + ' ' + verb, kick: PER[per] + ' · ' + lead[0].who, leadAmt: lead[0].amt, share: Math.round(lead[0].num / sum * 100), shareTxt: Math.round(lead[0].num / sum * 100) + '%',
    topDown: downs[0].name, topUp: ups[0].name, topDownAmt: downs[0].amt, topUpAmt: ups[0].amt, unit: U, perName: PER[per] };
}

