    build: (C) => `<section class="{{x.skyCls}}" style="--i:0" aria-label="Launch pad|發射台">${stars}<div class="hud"><div class="glass"><div class="kick">${ic('target', 16, 2.2)}Target|目標</div><div class="t1" style="font-size:20px;margin-top:4px">RT-AX86U · Maple-Home</div><div class="t2 mono">RT-AX86U:/jffs# reboot</div><div class="rowx" style="margin-top:8px">${C.tag('Four keys turned|四條鎖匙已扭', 'good')}${C.tag('Level 1 now|而家第 1 級')}</div></div><div class="glass" style="text-align:right;min-width:280px"><div class="kick" style="justify-content:flex-end">{{x.status}}</div><div class="cdbig"><sc-if value="{{x.hold}}" hint-placeholder-val="{{ false }}">10</sc-if><sc-if value="{{x.counting}}" hint-placeholder-val="{{ true }}"><span class="cd10" aria-label="10"></span><span class="cds">10</span></sc-if><sc-if value="{{x.gone}}" hint-placeholder-val="{{ false }}">0</sc-if><sc-if value="{{x.aborted}}" hint-placeholder-val="{{ false }}">${ic('x', 150, 2.4)}</sc-if></div><div class="t2">T minus, in seconds|倒數秒數</div></div></div><div class="mid"><sc-for list="{{x.checks}}" as="ck" hint-placeholder-count="5"><div class="{{ck.cls}}" style="{{ck.style}}"><span>{{ck.label}}</span><b>{{ck.word}}</b></div></sc-for></div><span class="tower" aria-hidden="true"></span><div class="rocket" aria-hidden="true">${rocket}<span class="flame"></span></div><span class="smoke" aria-hidden="true">${[-70, -30, 10, 50, 90].map((x, i) => `<i style="--x:${x}px;--d:${(i * 0.23).toFixed(2)}s"></i>`).join('')}</span><div class="pad"></div><div class="ctl"><sc-if value="{{x.hold}}" hint-placeholder-val="{{ false }}"><button class="btn wh hot dr w" onClick="{{x.start}}">${ic('play', 20)}<span>Start the count|開始倒數</span></button></sc-if><sc-if value="{{x.counting}}" hint-placeholder-val="{{ true }}"><button class="btn dng hot dr w" onClick="{{x.launch}}">${ic('rocket', 20)}<span>Launch now|即刻發射</span></button></sc-if><sc-if value="{{x.canAbort}}" hint-placeholder-val="{{ true }}"><button class="btn wh" onClick="{{x.abort}}">${ic('stop', 20)}<span>Abort|中止</span></button></sc-if><sc-if value="{{x.gone}}" hint-placeholder-val="{{ false }}"><a class="btn wh hot dr" href="RebootTimeline.dc.html">${ic('history', 20)}<span>Watch the reboot live|睇即時重啟</span></a></sc-if><sc-if value="{{x.canReset}}" hint-placeholder-val="{{ false }}"><button class="btn gh" onClick="{{x.reset}}">${ic('refresh', 20)}<span>Reset the pad|重設發射台</span></button></sc-if></div></section>`
